SELECT p.node_id,p.ca_id,p.ca_version,p.credential_id,p.credential_version FROM mtls_probe_versions p JOIN mtls_ca_generations g ON g.ca_id=p.ca_id AND g.ca_version=p.ca_version JOIN nodes n ON n.id=p.node_id JOIN credentials c ON c.id=g.ca_id WHERE g.state='published' AND NOT c.archived AND n.state NOT IN ('deleting','delete_failed') AND NOT p.discarded AND p.next_action_at<=(SELECT now FROM cutoff) AND NOT EXISTS(SELECT 1 FROM mtls_probe_versions newer WHERE newer.node_id=p.node_id AND newer.ca_id=p.ca_id AND newer.ca_version=p.ca_version AND newer.credential_version>p.credential_version AND NOT newer.discarded) AND EXISTS(SELECT 1 FROM mtls_node_trust t WHERE t.node_id=p.node_id AND t.ca_id=p.ca_id AND t.ca_version=p.ca_version AND (t.desired OR t.deployed)) AND NOT EXISTS(SELECT 1 FROM background_work w WHERE w.id='mtls-probe:'||p.node_id||':'||p.ca_id||':'||p.ca_version::text AND w.state IN ('queued','running'))
